def f(I_):
    H_,W_=len(I_),len(I_[0])
    from collections import Counter as C
    bgv=C(x for r in I_ for x in r).most_common(1)[0][0]
    out=[r[:] for r in I_]
    seen=[[False]*W_ for _ in range(H_)]
    for y in range(H_):
        for x in range(W_):
            if I_[y][x]!=bgv and not seen[y][x]:
                ccol=I_[y][x]; q=[(y,x)]; seen[y][x]=True; cs=[]
                while q:
                    cy,cx=q.pop(); cs.append((cy,cx))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=cy+dy,cx+dx
                        if 0<=ny<H_ and 0<=nx<W_ and not seen[ny][nx] and I_[ny][nx]==ccol:
                            seen[ny][nx]=True; q.append((ny,nx))
                ys=[p[0] for p in cs]; xs=[p[1] for p in cs]
                top,bot,l,r=min(ys),max(ys),min(xs),max(xs)
                for cy,cx in cs:
                    if top<cy<bot and l<cx<r: out[cy][cx]=8
    return out
