    H,W=len(I_),len(I_[0])
    out=[r[:] for r in I_]
    for y in range(H):
        for x in range(W):
            if 1<=y<H-1 and 1<=x<W-1:
                v=I_[y][x]
                if I_[y-1][x]==v and I_[y+1][x]==v and I_[y][x-1]==v and I_[y][x+1]==v:
                    out[y][x]=8
    return out
